$out="$env:TEMP\ov_q"; @'
import fs from "fs";
const d="C:\\Users\\Administrator\\Documents\\deepseek-harness\\default-workspace\\memory-migration\\out\\distilled-projects\\园区物管2.0";
const files=fs.readdirSync(d).filter(f=>f.endsWith(".json")).sort();
const j=JSON.parse(fs.readFileSync(d+"\\"+files[0],"utf8"));
console.log("BATCH FILE:",files[0],"| project:",j.project,"| count:",j.memories.length);
const m=j.memories[0];
console.log("KEYS:",Object.keys(m).join(", "));
console.log("TYPE:",m.type,"| TITLE:",m.title);
console.log("CONTENT_LEN:",(m.content||"").length);
console.log("FILES:",JSON.stringify(m.files));
console.log("SESSION_IDS:",JSON.stringify(m.sessionIds));
console.log("BASELINE:",JSON.stringify(m.baseline).slice(0,150));
fs.writeFileSync("C:\\Users\\ADMINI~1\\AppData\\Local\\Temp\\ov_q\\sample.json",JSON.stringify(m,null,1),"utf8");
'@ | Set-Content "$out\q2.mjs" -Encoding UTF8; node "$out\q2.mjs"

$out="$env:TEMP\ov_q"; @'
import fs from "fs";
const T="C:\\Users\\ADMINI~1\\AppData\\Local\\Temp\\ov_q";
const m=JSON.parse(fs.readFileSync(T+"\\sample.json","utf8"));
const sid="q-"+Date.now();
// 按「已提炼」格式组织：把结构化字段显式写进文本
const text=[
`【记忆类型】${m.type}`,
`【标题】${m.title}`,
`【项目】${m.project}`,
`【内容】${m.content}`,
`【证据】${m.evidence||""}`,
`【涉及文件】${(m.files||[]).join("; ")}`,
`【来源会话】${(m.sessionIds||[]).join(", ")}`,
`【代码基线】${m.baseline||""}`
].join("\n");
fs.writeFileSync(T+"\\payload.txt",text,"utf8");
console.log("PAYLOAD_CHARS:",text.length);
const r=await fetch(`http://127.0.0.1:1933/api/v1/sessions/${sid}/messages/batch`,{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify({messages:[{role:"user",message_kind:"user_query",content:text}]})});
console.log("ADD:",r.status,(await r.text()).slice(0,200));
const rc=await fetch(`http://127.0.0.1:1933/api/v1/sessions/${sid}/commit`,{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify({})});
const cj=await rc.json();
console.log("COMMIT:",rc.status,JSON.stringify(cj.result||cj).slice(0,300));
fs.writeFileSync(T+"\\tid.txt",cj.result?.task_id||"","utf8");
fs.writeFileSync(T+"\\sid.txt",sid,"utf8");
'@ | Set-Content "$out\q3.mjs" -Encoding UTF8; node "$out\q3.mjs"

Start-Sleep -Seconds 75; $out="$env:TEMP\ov_q"; @'
import fs from "fs";
const T="C:\\Users\\ADMINI~1\\AppData\\Local\\Temp\\ov_q";
const tid=fs.readFileSync(T+"\\tid.txt","utf8").trim();
const r=await fetch(`http://127.0.0.1:1933/api/v1/tasks/${tid}`);
const j=await r.json();
const list=Array.isArray(j)?j:(Array.isArray(j.result)?j.result:[j.result||j]);
const t=list.find(x=>x&&x.task_id===tid)||{};
console.log("status:",t.status,"| secs:",Math.round(t.processing_seconds||0));
console.log("extracted:",JSON.stringify(t.result?.memories_extracted));
console.log("tokens:",JSON.stringify(t.result?.token_usage?.total));
'@ | Set-Content "$out\q4.mjs" -Encoding UTF8; node "$out\q4.mjs"

